import {esc,btn} from './views.js';
import {hasDraft} from './workspace-flow.js';
import {completedIds,STEPS} from './guidance.js';
import {creditsOf} from './planner.js';
export function homeView(state,account=null){
 const plan=state.plan,draft=hasDraft(state),name=account?.firstName||plan?.profile?.name,returning=!!(plan||draft);
 const done=plan?completedIds(plan):[],completed=plan?creditsOf(plan.courses.filter(c=>done.includes(c.id))):0,total=plan?creditsOf(plan.courses):0;
 const outline=`<aside class="start-outline" aria-label="Your planning journey"><span class="eyebrow">ONE STEP AT A TIME</span><ol>${STEPS.map((step,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><strong>${step}</strong></li>`).join('')}</ol><p>A roadmap you can keep, adjust and grow with.</p></aside>`;
 return `<section class="welcome"><div class="welcome-heading"><span class="eyebrow">YOUR PERSONAL ACADEMIC WORKSPACE</span><h1>${returning||account?'Welcome back'+(name?', '+esc(name):'')+'.':'Let’s find your direction.'}</h1><p class="welcome-lead">${plan?'Your plan is here. Pick up where you left off, or make room for a new direction.':draft?'Your answers are saved. Continue when you’re ready.':'Connect what matters to you with what you study next.'}</p></div>${returning?`<div class="welcome-options"><article class="welcome-card welcome-saved"><span class="eyebrow">${plan?'YOUR SAVED ROADMAP':'YOUR PLAN IN PROGRESS'}</span><h2>${esc(plan?.program?.name||'A direction that’s taking shape.')}</h2>${plan?`<div class="home-progress"><div><span>Degree progress</span><strong>${completed} <span>/ ${total} credits</span></strong></div><progress value="${completed}" max="${Math.max(1,total)}" aria-label="Degree credits completed"></progress></div>`:`<p>Next up: ${esc(STEPS[state.journey.step])}<span class="home-step">Step ${state.journey.step+1} of 6</span></p>`}<div class="card-actions">${btn('resume-plan',draft?'Continue planning':'Open my roadmap',true)}${plan?btn('change-plan','Change my plan'):''}</div>${draft&&plan?btn('open-saved','View saved roadmap'):''}</article><article class="welcome-card quiet"><span class="eyebrow">A NEW BEGINNING</span><h2>A fresh perspective.</h2><p>Start with a blank page. Previous answers, choices and progress won’t shape your new plan.</p>${btn('fresh-start','Start fresh')}</article></div>`:`<div class="start-workspace"><article class="start-main"><span class="eyebrow">DESIGNED AROUND YOU</span><h2>Your ambitions.<br>Your path through AUI.</h2><p>Tell your adviser what you enjoy and where you want to go. Explore your options, then shape a plan that fits.</p>${btn(account?'resume-plan':'fresh-start','Build my plan',true)}<span class="start-reassurance">No degree in mind? That’s a good place to start.</span></article>${outline}</div>`}<div class="welcome-note"><span>${account?'Saved to your account. Ready on your other devices.':'Sign in to keep your plan across devices.'}</span></div></section>`;
}
